```rust
pub fn kv_head_for(&self, q_head: usize) -> usize {
    let ratio = self.n_head / self.n_kv_head;
    debug_assert!(ratio > 0, "n_head must be >= n_kv_head");
    let h = q_head / ratio;
    if h >= self.n_kv_head { self.n_kv_head - 1 } else { h }
}
